import{_ as e,C as i,c as s,o as t,j as r,G as l,b as a,a0 as o,a as n,w as u,a1 as c}from"./chunks/framework.DKRgXLPU.js";const d=JSON.parse('{"title":"Réflexion tactique à la pétanque","description":"","frontmatter":{},"headers":[],"relativePath":"fr/education/tactics/index.md","filePath":"fr/education/tactics/index.md"}');const p=e({name:"fr/education/tactics/index.md"},[["render",function(e,d,p,m,v,h){const b=i("AdBanner"),g=i("Mermaid");return t(),s("div",null,[d[2]||(d[2]=r("h1",{id:"reflexion-tactique-a-la-petanque",tabindex:"-1"},[n("Réflexion tactique à la pétanque "),r("a",{class:"header-anchor",href:"#reflexion-tactique-a-la-petanque","aria-label":'Permalink to "Réflexion tactique à la pétanque"'},"​")],-1)),l(b),d[3]||(d[3]=r("p",null,"Au plus haut niveau, la maîtrise technique est acquise. Ce qui distingue les vainqueurs, c'est l'intelligence tactique : savoir quel coup tenter et à quel moment. Les meilleurs joueurs anticipent le jeu plusieurs coups à l'avance et exploitent le moindre avantage.",-1)),d[4]||(d[4]=r("div",{class:"tip custom-block"},[r("p",{class:"custom-block-title"},"Le principe fondamental"),r("p",null,[r("strong",null,"Au plus haut niveau, la différence réside rarement dans la technique, mais dans la prise de décision."),n(" L'équipe qui commet le moins d'erreurs tactiques l'emporte.")])],-1)),d[5]||(d[5]=r("h2",{id:"cadre-de-decision-rapide",tabindex:"-1"},[n("Cadre de décision rapide "),r("a",{class:"header-anchor",href:"#cadre-de-decision-rapide","aria-label":'Permalink to "Cadre de décision rapide"'},"​")],-1)),(t(),a(c,null,{default:u(()=>[l(g,{id:"mermaid-16",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5B%C3%80%20votre%20tour%5D%20--%3E%20B%7BAre%20you%20holding%3F%7D%0A%20%20%20%20B%20--%3E%7CYes%7C%20C%7BOpponent%20has%20boules%3F%7D%0A%20%20%20%20B%20--%3E%7CNo%7C%20D%7BCan%20you%20point%20closer%3F%7D%0A%0A%20%20%20%20C%20--%3E%7CYes%7C%20E%5BAttendez%20et%20planifiez%5D%0A%20%20%20%20C%20--%3E%7CNo%7C%20F%7BSafe%20to%20add%20points%3F%7D%0A%0A%20%20%20%20F%20--%3E%7CYes%7C%20G%5BAjoutez%20les%20points%20avec%20pr%C3%A9caution%5D%0A%20%20%20%20F%20--%3E%7CNo%7C%20H%5BJouez%20en%20toute%20s%C3%A9curit%C3%A9%2Fbloquez%5D%0A%0A%20%20%20%20D%20--%3E%7CYes%2C%20high%20%25%7C%20I%5BIndiquer%5D%0A%20%20%20%20D%20--%3E%7CPeut%20%C3%AAtre%7C%20J%7BCan%20you%20shoot%3F%7D%0A%20%20%20%20D%20--%3E%7CNo%7C%20K%5BD%C3%A9placez%20le%20cric%20ou%20le%20bloc%5D%0A%0A%20%20%20%20J%20--%3E%7CYes%2C%20%3E60%25%7C%20L%5BTirer%5D%0A%20%20%20%20J%20--%3E%7CNo%7C%20K%0A%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23fff3e0%0A%20%20%20%20style%20F%20fill%3A%23fff3e0%0A%20%20%20%20style%20J%20fill%3A%23ffebee%0A"})]),fallback:u(()=>[...d[0]||(d[0]=[n(" Loading... ",-1)])]),_:1})),d[6]||(d[6]=o('<h2 id="l-39-etat-d-39-esprit-tactique" tabindex="-1">L&#39;état d&#39;esprit tactique <a class="header-anchor" href="#l-39-etat-d-39-esprit-tactique" aria-label="Permalink to &quot;L&amp;#39;état d&amp;#39;esprit tactique&quot;">​</a></h2><h3 id="penser-en-termes-de-probabilites" tabindex="-1">Penser en termes de probabilités <a class="header-anchor" href="#penser-en-termes-de-probabilites" aria-label="Permalink to &quot;Penser en termes de probabilités&quot;">​</a></h3><p>Chaque lancer a une probabilité de succès. Une bonne tactique consiste à choisir des lancers où :</p><ul><li>La probabilité de succès est suffisamment élevée</li><li>La récompense justifie le risque</li><li>L&#39;échec ne fait pas trop mal.</li></ul><p><strong>Exemple de décision :</strong></p><ul><li>Tir difficile : 40 % de réussite, rapporte 3 points</li><li>Point de sécurité : 80 % de réussite, gain de 1 point</li></ul><p>Quel est le meilleur choix ? Cela dépend du score, de la situation et de votre confiance.</p><h3 id="examinez-toutes-les-options" tabindex="-1">Examinez toutes les options <a class="header-anchor" href="#examinez-toutes-les-options" aria-label="Permalink to &quot;Examinez toutes les options&quot;">​</a></h3><p>Avant chaque lancer, réfléchissez :</p><ol><li><strong>Point :</strong> Placez une boule près du cochonnet</li><li><strong>Tir :</strong> Retirez la boule d&#39;un adversaire</li><li><strong>Blocage :</strong> Placez une boule pour bloquer</li><li><strong>Déplacer le cric :</strong> Frapper intentionnellement le cric</li><li><strong>Sacrifice :</strong> Accepter une mauvaise position pour mieux se préparer plus tard</li></ol><p>Ne vous contentez pas de la solution évidente. Réfléchissez aux alternatives.</p><h3 id="lire-la-situation" tabindex="-1">Lire la situation <a class="header-anchor" href="#lire-la-situation" aria-label="Permalink to &quot;Lire la situation&quot;">​</a></h3><p>Facteurs à prendre en compte :</p><ul><li>Score actuel (qui est en tête, et de combien)</li><li>Boules restantes (les vôtres et les leurs)</li><li>Position sur le terrain</li><li>Tendances adverses</li><li>Les points forts de votre équipe</li></ul><h2 id="principes-tactiques-fondamentaux" tabindex="-1">Principes tactiques fondamentaux <a class="header-anchor" href="#principes-tactiques-fondamentaux" aria-label="Permalink to &quot;Principes tactiques fondamentaux&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Les 6 principes tactiques</p><ol><li><strong>Contrôlez le cric</strong> - La position est la puissance</li><li><strong>Stratégie de distance et de surface</strong> - S&#39;adapter aux conditions</li><li><strong>Dictez le style de jeu</strong> - Mettez vos points forts en avant</li><li><strong>Gérer le rapport risque/récompense</strong> - Adapter le risque à la situation</li><li><strong>Utilisez les boules judicieusement</strong> - Parfois, concéder 1 point permet d&#39;en éviter 3</li><li><strong>Anticipez</strong> - Visualisez les 2 ou 3 prochains mouvements</li></ol></div><h3 id="principe-1-controler-le-cric" tabindex="-1">Principe 1 : Contrôler le cric <a class="header-anchor" href="#principe-1-controler-le-cric" aria-label="Permalink to &quot;Principe 1 : Contrôler le cric&quot;">​</a></h3><p>L&#39;équipe qui contrôle la position du cochonnet possède un avantage significatif.</p><p><strong>Moyens de contrôle :</strong></p><ul><li>Gagnez le droit de lancer le jack</li><li>Déplacez le cric vers un terrain favorable.</li><li>Protéger le cric contre tout déplacement</li></ul><p><strong>Stratégie de placement des crics :</strong></p><ul><li>Jack court : Favorise le tir, plus facile d&#39;atteindre les cibles à courte portée</li><li>Long jack : Favorise le pointage, le tir devient plus difficile</li><li>Obstacles proches : créent des difficultés pour les adversaires</li></ul><p><strong>Exploiter les faiblesses de l&#39;adversaire :</strong></p><ul><li>Observez leur technique de désignation : utilisent-ils toujours le même arc ou le même style ?</li><li>S&#39;ils ne peuvent pas s&#39;adapter (par exemple, ne font que rouler, ne font que lober), placez le cochonnet pour les forcer à lancer dans des conditions difficiles.</li><li>Placez le cric à des distances ou dans des positions qui mettent en évidence ses limites.</li><li>N&#39;exploitez une faiblesse que si vous ne la partagez pas ; commencez par considérer les forces de votre propre équipe.</li></ul><h3 id="principe-2-strategie-de-distance-et-de-surface" tabindex="-1">Principe 2 : Stratégie de distance et de surface <a class="header-anchor" href="#principe-2-strategie-de-distance-et-de-surface" aria-label="Permalink to &quot;Principe 2 : Stratégie de distance et de surface&quot;">​</a></h3><p>L&#39;équilibre optimal entre viser et tirer dépend fortement de la distance et du terrain :</p><div class="info custom-block"><p class="custom-block-title">Stratégie de distance</p><p><strong>Court (6-7 m) :</strong> Privilégiez le tir - plus facile à toucher à courte distance <strong>Moyen (7-9 m) :</strong> La surface est primordiale</p><ul><li>Surface lisse → prendre plus de photos</li><li>Surface rugueuse → pointer plus</li></ul><p><strong>Longue distance (9-11 m) :</strong> Privilégiez le pointage – la précision de tir diminue considérablement</p></div>',27)),(t(),a(c,null,{default:u(()=>[l(g,{id:"mermaid-264",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BDistance%5D%20--%3E%20B%5B6-7%20m%20Court%5D%0A%20%20%20%20A%20--%3E%20C%5B7-9%20m%20Moyen%5D%0A%20%20%20%20A%20--%3E%20D%5B9%20%C3%A0%2011%20m%20de%20long%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BTirez%20davantage%5D%0A%20%20%20%20C%20--%3E%20F%7BSurface%3F%7D%0A%20%20%20%20D%20--%3E%20G%5BPoint%20More%5D%0A%0A%3CAdInArticle%20%2F%3E%0A%0A%20%20%20%20F%20--%3E%7CSmooth%7C%20H%5BTirez%20davantage%5D%0A%20%20%20%20F%20--%3E%7CRough%7C%20I%5BPoint%20More%5D%0A%0A%20%20%20%20style%20E%20fill%3A%23ffcdd2%0A%20%20%20%20style%20H%20fill%3A%23ffcdd2%0A%20%20%20%20style%20I%20fill%3A%23c8e6c9%0A%20%20%20%20style%20G%20fill%3A%23c8e6c9%0A"})]),fallback:u(()=>[...d[1]||(d[1]=[n(" Loading... ",-1)])]),_:1})),d[7]||(d[7]=o('<p><strong>Votre pourcentage de réussite au tir personnel :</strong></p><ul><li>Si vous avez un taux de réussite de plus de 75 %, tirez plus souvent.</li><li>Envisagez de tirer pour réduire le nombre de points de votre adversaire (même si vous ne prenez pas l&#39;avantage).</li><li>Tirer pour réduire le nombre de boules de score de l&#39;adversaire (de 3 à 1) est un moyen précieux de contrôler les dégâts.</li></ul><p><strong>Le tir comme stratégie à long terme :</strong></p><ul><li>Si vous tirez avec toutes vos boules, tenez compte de votre taux de réussite cumulé.</li><li>Calcul : lorsque vous réussissez tous vos tirs, vous gagnez beaucoup plus de points.</li><li>Même rater quelques tirs peut réduire le nombre de points de l&#39;adversaire</li><li>Exemple : Rater 1 ou 2 tirs, mais éliminer les menaces, puis remporter une victoire éclatante en touchant tous les ennemis.</li><li>C&#39;est un risque calculé : accepter quelques pertes pour espérer de plus gros gains lorsque cela fonctionne.</li></ul><h3 id="principe-3-imposer-le-style-de-jeu" tabindex="-1">Principe 3 : Imposer le style de jeu <a class="header-anchor" href="#principe-3-imposer-le-style-de-jeu" aria-label="Permalink to &quot;Principe 3 : Imposer le style de jeu&quot;">​</a></h3><p>Au plus haut niveau, la plupart des joueurs savent viser et tirer avec précision. L&#39;essentiel est d&#39;imposer le style de jeu qui convient le mieux à son équipe.</p><p><strong>Si votre équipe compte de bons tireurs :</strong></p><ul><li>Tirez autant que possible - exploitez votre avantage</li><li>Ne gaspillez pas votre énergie à pointer du doigt quand vous pouvez dominer par le tir.</li><li>Contrôlez le jeu en éliminant les menaces avant qu&#39;elles ne s&#39;accumulent.</li><li>Les jacks de courte à moyenne taille conservent une efficacité de tir</li></ul><p><strong>Contre des tireurs d&#39;égale force :</strong></p><ul><li>Ne leur facilitez pas la tâche en tirant le premier. Empêchez-les de devenir des cibles faciles.</li><li>Jouez à longue distance pour réduire le pourcentage de réussite au tir de chacun.</li><li>L&#39;équipe qui tire en premier contrôle souvent la fin du match.</li></ul><p><strong>Si vos adversaires sont plus précis que vous au tir :</strong></p><ul><li>Jouez le long jack de manière constante - même les tireurs d&#39;élite voient leur pourcentage chuter à plus de 10 m</li><li>Forcez un duel de points où vous pouvez rivaliser</li><li>Faites-les tirer sous des angles difficiles ou à travers des obstacles</li></ul><h3 id="principe-4-gerer-le-risque-par-rapport-a-la-recompense" tabindex="-1">Principe 4 : Gérer le risque par rapport à la récompense <a class="header-anchor" href="#principe-4-gerer-le-risque-par-rapport-a-la-recompense" aria-label="Permalink to &quot;Principe 4 : Gérer le risque par rapport à la récompense&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Situation</th><th>Tolérance au risque</th></tr></thead><tbody><tr><td>En avant confortablement</td><td>Faible - protégez votre plomb</td></tr><tr><td>Match serré</td><td>Moyen - risques calculés</td></tr><tr><td>En retard de manière significative</td><td>Niveau élevé - il faut prendre des risques</td></tr><tr><td>Fin définitive</td><td>Cela dépend de l&#39;écart de score</td></tr></tbody></table><h3 id="principe-5-utilisez-vos-boules-judicieusement" tabindex="-1">Principe 5 : Utilisez vos boules judicieusement <a class="header-anchor" href="#principe-5-utilisez-vos-boules-judicieusement" aria-label="Permalink to &quot;Principe 5 : Utilisez vos boules judicieusement&quot;">​</a></h3><p>La direction de la boule sépare les joueurs d&#39;élite :</p><ul><li>Lorsque votre adversaire n&#39;a plus de boules, réfléchissez bien : faut-il marquer des points ou jouer la sécurité ?</li><li>Lorsque vous êtes mené, évaluez si vous pouvez raisonnablement reprendre le point.</li><li>Parfois, concéder un point est préférable à gaspiller des boules et à en perdre trois.</li><li>Gardez toujours une trace des boules restantes — les vôtres et les leurs — à tout moment</li></ul><h3 id="principe-6-anticiper-plusieurs-actions-a-l-avance" tabindex="-1">Principe 6 : Anticiper plusieurs actions à l’avance <a class="header-anchor" href="#principe-6-anticiper-plusieurs-actions-a-l-avance" aria-label="Permalink to &quot;Principe 6 : Anticiper plusieurs actions à l’avance&quot;">​</a></h3><p>Pensée élitiste :</p><ul><li>Avant de lancer, visualisez les 2 ou 3 prochaines boules des deux équipes.</li><li>Quelle est la meilleure réponse de votre adversaire si vous réussissez ? Et si vous échouez ?</li><li>Comment ce lancer prépare-t-il le suivant ?</li><li>Considérons le scénario de fin de partie à partir de la position actuelle.</li></ul><h2 id="situations-tactiques-courantes" tabindex="-1">Situations tactiques courantes <a class="header-anchor" href="#situations-tactiques-courantes" aria-label="Permalink to &quot;Situations tactiques courantes&quot;">​</a></h2><h3 id="vous-detenez-les-boules-et-votre-adversaire-en-a-encore" tabindex="-1">Vous détenez les boules et votre adversaire en a encore. <a class="header-anchor" href="#vous-detenez-les-boules-et-votre-adversaire-en-a-encore" aria-label="Permalink to &quot;Vous détenez les boules et votre adversaire en a encore.&quot;">​</a></h3><p>Vous devez attendre, c&#39;est à leur tour de lancer. Profitez-en pour :</p><ul><li>Analysez ce qu&#39;ils sont susceptibles de faire.</li><li>Préparez votre réponse à leurs possibles lancers.</li><li>Restez concentré et prêt</li></ul><h3 id="vous-detenez-la-boule-et-votre-adversaire-n-39-a-plus-de-boules" tabindex="-1">Vous détenez la boule et votre adversaire n&#39;a plus de boules. <a class="header-anchor" href="#vous-detenez-la-boule-et-votre-adversaire-n-39-a-plus-de-boules" aria-label="Permalink to &quot;Vous détenez la boule et votre adversaire n&amp;#39;a plus de boules.&quot;">​</a></h3><p>Vous pouvez maintenant jouer vos boules restantes. <strong>Options :</strong></p><ul><li>Ajoutez plus de points si vous pouvez le faire en toute sécurité</li><li>Bloc pour protéger contre le mouvement du cric</li><li>Jouez la sécurité – ne risquez pas de transformer une victoire de 2 points en défaite</li></ul><p><strong>Décision clé :</strong> Le risque d&#39;ajouter des points vaut-il la peine de potentiellement ouvrir le jeu ?</p><h3 id="vous-ne-tenez-pas" tabindex="-1">Vous ne tenez pas <a class="header-anchor" href="#vous-ne-tenez-pas" aria-label="Permalink to &quot;Vous ne tenez pas&quot;">​</a></h3><p>Vous devez lancer. <strong>Options :</strong></p><ul><li>Point plus près que leur meilleure boule</li><li>Tirez leur meilleure boule</li><li>Déplacez le cochonnet vers vos boules</li><li>Bloquez pour limiter leur score (si vous ne pouvez pas prendre le point).</li></ul><p><strong>Facteurs de décision :</strong> Votre pourcentage de réussite au tir, le nombre de boules restantes (pour les deux équipes), le score actuel</p><h3 id="dernieres-situations-de-boule" tabindex="-1">Dernières situations de boule <a class="header-anchor" href="#dernieres-situations-de-boule" aria-label="Permalink to &quot;Dernières situations de boule&quot;">​</a></h3><p>Quand vous avez la dernière boule :</p><ul><li>Pression maximale, mais aussi contrôle maximal</li><li>Prenez votre temps – évaluez toutes les options</li><li>Réfléchissez : pointer, tirer ou déplacer le cric ?</li><li>Exécuter avec un engagement total</li></ul><p>Lorsque l&#39;adversaire a la dernière boule :</p><ul><li>Tu as fait tout ce que tu pouvais – accepte le résultat.</li><li>Si possible, créez une situation qui ne leur offre pas de solution facile.</li><li>Plusieurs menaces valent mieux qu&#39;une seule.</li></ul><h2 id="lire-ses-adversaires" tabindex="-1">Lire ses adversaires <a class="header-anchor" href="#lire-ses-adversaires" aria-label="Permalink to &quot;Lire ses adversaires&quot;">​</a></h2><p>Au plus haut niveau, le repérage des adversaires est essentiel. Il faut connaître ses adversaires avant de jouer.</p><h3 id="renseignements-d-39-avant-match" tabindex="-1">Renseignements d&#39;avant-match <a class="header-anchor" href="#renseignements-d-39-avant-match" aria-label="Permalink to &quot;Renseignements d&amp;#39;avant-match&quot;">​</a></h3><ul><li>Quel est leur style de jeu préféré (équipe de tir ou équipe de pointage) ?</li><li>Qui est leur meilleur tireur ? Pointer ?</li><li>Quelles distances préfèrent-ils ?</li><li>Comment réagissent-ils sous pression lors des finales ?</li></ul><h3 id="observation-en-cours-de-match" tabindex="-1">Observation en cours de match <a class="header-anchor" href="#observation-en-cours-de-match" aria-label="Permalink to &quot;Observation en cours de match&quot;">​</a></h3><ul><li>Suivez leurs taux de réussite tout au long du match.</li><li>Remarquez si quelqu&#39;un passe une mauvaise journée.</li><li>Identifiez les personnes qui gèrent bien la pression et celles qui ne la gèrent pas.</li><li>Ajustez l&#39;emplacement de votre cric en fonction de ce que vous observez.</li></ul><h3 id="exploitez-ce-que-vous-trouvez" tabindex="-1">Exploitez ce que vous trouvez <a class="header-anchor" href="#exploitez-ce-que-vous-trouvez" aria-label="Permalink to &quot;Exploitez ce que vous trouvez&quot;">​</a></h3><ul><li>Ciblez les joueurs les plus faibles lorsque c&#39;est possible.</li><li>Forcez leur tireur faible à tirer, ou leur pointeur faible à pointer.</li><li>Si quelqu&#39;un est en difficulté, maintenez la pression sur lui.</li></ul><h2 id="dans-cette-section" tabindex="-1">Dans cette section <a class="header-anchor" href="#dans-cette-section" aria-label="Permalink to &quot;Dans cette section&quot;">​</a></h2><ul><li><strong><a href="/en/education/tactics/probability">Décisions basées sur les probabilités</a></strong> - Utiliser les mathématiques pour faire de meilleurs choix</li></ul><h2 id="resume-toutes-les-regles-tactiques" tabindex="-1">Résumé : Toutes les règles tactiques <a class="header-anchor" href="#resume-toutes-les-regles-tactiques" aria-label="Permalink to &quot;Résumé : Toutes les règles tactiques&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Règle n° 1 : La règle des probabilités</p><p><strong>Choisissez les lancers où la probabilité de succès justifie le risque.</strong> Considérons : le taux de réussite, la récompense en cas de succès, le coût en cas d&#39;échec.</p></div><div class="tip custom-block"><p class="custom-block-title">Règle n° 2 : La règle de contrôle du jack</p><p><strong>L&#39;équipe qui contrôle la position du jack a l&#39;avantage.</strong> Utilisez le placement des jacks pour exploiter les faiblesses de l&#39;adversaire et favoriser vos forces.</p></div><div class="tip custom-block"><p class="custom-block-title">Règle n° 3 : La règle de la distance</p><p><strong>À courte distance, il est préférable de tirer ; à longue distance, il est préférable de viser.</strong> Moyenne distance : la qualité de la surface détermine l&#39;équilibre</p></div><div class="tip custom-block"><p class="custom-block-title">Règle n° 4 : La règle du style</p><p><strong>Imposer le style de jeu le plus avantageux pour votre équipe.</strong> Si vous êtes de bons tireurs, tirez davantage. Ne gaspillez pas votre avantage.</p></div><div class="tip custom-block"><p class="custom-block-title">Règle n° 5 : La règle de gestion de boule</p><p><strong>Parfois, concéder 1 point vaut mieux que d&#39;en risquer 3.</strong> Sachez quand limiter vos pertes et garder vos boules pour la prochaine manche.</p></div><div class="tip custom-block"><p class="custom-block-title">Règle n° 6 : La règle de la prévoyance</p><p><strong>Visualisez les 2 ou 3 prochains mouvements des deux équipes.</strong> Quelle est leur meilleure réponse ? Comment cela prépare-t-il votre prochain lancer ?</p></div><div class="tip custom-block"><p class="custom-block-title">Règle n° 7 : La règle du scoutisme</p><p><strong>Renseignez-vous sur vos adversaires avant de jouer.</strong> Suivre leurs préférences, leurs taux de réussite et leurs réactions à la pression.</p></div><h2 id="points-cles-a-retenir" tabindex="-1">Points clés à retenir <a class="header-anchor" href="#points-cles-a-retenir" aria-label="Permalink to &quot;Points clés à retenir&quot;">​</a></h2><blockquote><p>Au plus haut niveau, la différence réside rarement dans la technique, mais dans la prise de décision. L&#39;équipe qui commet le moins d&#39;erreurs tactiques l&#39;emporte.</p></blockquote><p>Analysez le jeu. Connaissez vos points forts. Exploitez les faiblesses de l&#39;adversaire. Agissez avec assurance.</p>',58)),l(b)])}]]);export{d as __pageData,p as default};
